-- united-states.california.antelope-valley-of-the-california-high-desert
insert into public.wine_place_articles (wine_place_id, description, climate, soils, grape_varieties, wine_styles, key_facts, editorial_status)
select id, 'A high-desert valley of about 665 square miles in Los Angeles and Kern counties, north of the San Gabriel Mountains, with a floor at 2,300 to 3,100 feet walled by mountains on three sides. Vines were planted here in the 1880s and 1890s; modern planting began in 1981, and by 2007 there were about 128 acres in 16 vineyards.', 'Hot, dry summers and cold winters, Winkler Region V at about 4,600 growing degree days, with only 4 to 9 inches of rain and winter lows of 6 to 11 °F.', 'Deep, loamy, well-drained alluvial soils from granite, such as the Hesperia-Rosamond-Cajon and Hanford-Ramona-Greenfield associations.', 'Cabernet Sauvignon, Tempranillo and Malbec, with Muscat, on the estates of the valley.', 'Dry red wines from Cabernet Sauvignon, Tempranillo and Malbec.', array['Established 2011 (27 CFR 9.219)', 'About 665 square miles (TTB final rule)', 'About 128 acres in 16 vineyards in 2007 (TTB final rule)', 'Spans Los Angeles and Kern counties']::text[], 'PUBLISHED'
  from public.wine_places where canonical_key = 'united-states.california.antelope-valley-of-the-california-high-desert';
