-- united-states.california.central-coast.monterey.hames-valley
insert into public.wine_place_articles (wine_place_id, description, climate, soils, grape_varieties, wine_styles, key_facts, editorial_status)
select id, 'The southernmost Monterey County AVA, a valley of about 10,240 acres near Bradley toward the San Luis Obispo county line, at about 472 to 1,289 feet. About 2,200 acres are planted, and its growers favour Rhône varieties as well as Bordeaux ones.', 'Very warm with little coastal influence, and the widest day-to-night swing of the Monterey County AVAs.', 'Lockwood shaly loam and Chamise shaly loam.', 'Rhône varieties such as Syrah and Petite Sirah, with Cabernet Sauvignon and other Bordeaux varieties.', 'Dry red wines from Rhône and Bordeaux varieties.', array['Established 1994 (27 CFR 9.147)', 'About 2,200 acres planted (Monterey County Vintners & Growers)', 'Elevations from about 472 to 1,289 feet (Monterey County Vintners & Growers)']::text[], 'PUBLISHED'
