-- united-states.california.central-coast.monterey.san-lucas
insert into public.wine_place_articles (wine_place_id, description, climate, soils, grape_varieties, wine_styles, key_facts, editorial_status)
select id, 'An AVA of about 33,920 acres in the southern Salinas Valley around the town of San Lucas, south of King City, at about 325 to 1,250 feet. About 8,000 acres are planted. In 2004 about 1,281 acres of its northwest corner went to San Bernabe so that a large vineyard would not be split.', 'Moderate to warm with much less cooling from Monterey Bay than further north; summer temperatures can swing as much as 40 °F.', 'Lockwood shaly loam and the Snelling-Greenfield complex.', 'Cabernet Sauvignon and Chardonnay, with Merlot and Sauvignon Blanc.', 'Dry red wines from Cabernet Sauvignon and Merlot, and dry whites.', array['Established 1987 (27 CFR 9.56)', 'About 8,000 acres planted (Monterey County Vintners & Growers)', 'Boundary realigned with San Bernabe in 2004 (T.D. TTB-14)']::text[], 'PUBLISHED'
