-- united-states.california.central-coast.san-antonio-valley
insert into public.wine_place_articles (wine_place_id, description, climate, soils, grape_varieties, wine_styles, key_facts, editorial_status)
select id, 'A basin of about 150,400 acres in southwestern Monterey County, the watershed of the San Antonio River, encircled by the Santa Lucia Range between the Pacific and the Salinas Valley. It is named after Mission San Antonio de Padua, founded in 1771. Over 700 acres were planted at establishment.', 'Shut off from marine air by the mountains: drier, hotter summer days and cooler nights, over 3,000 degree days, and wider seasonal swings than its neighbours.', 'Around 40 soil series, mostly alluvial on flat to gentle slopes, including Arbuckle gravelly loam, Lockwood loam and Placentia sandy loam.', 'Cabernet Sauvignon, Petite Sirah and Syrah, with Grenache, Tempranillo and Marsanne among some 20 varieties.', 'Dry red wines from Cabernet Sauvignon, Petite Sirah and Rhône varieties.', array['Established 2006 (27 CFR 9.194)', 'About 150,400 acres; elevations from about 850 to 2,530 feet (T.D. TTB-46)', 'Named after Mission San Antonio de Padua, founded in 1771 (T.D. TTB-46)']::text[], 'PUBLISHED'
  from public.wine_places where canonical_key = 'united-states.california.central-coast.san-antonio-valley';
