-- united-states.california.central-coast.san-benito
insert into public.wine_place_articles (wine_place_id, description, climate, soils, grape_varieties, wine_styles, key_facts, editorial_status)
select id, 'An AVA of about 45,000 acres in San Benito County, south of Hollister, between the Gabilan and Diablo ranges. It holds Cienega Valley, Lime Kiln Valley and Paicines, and some of the oldest vineyards in California; Almaden farmed much of it from the 1950s.', 'Moderate, with a maritime influence from Monterey Bay, about 20 miles away, and afternoon breezes; the mountain ranges shelter the valleys.', 'Varied, because of seismic activity: soils shift from granite to limestone within feet, with ancient seabed deposits.', 'Pinot Noir and Chardonnay make up more than half the county''s vineyard; Cabernet Sauvignon, Merlot and Zinfandel grow in the warmer spots.', 'Dry Chardonnay and Pinot Noir, and red wines from older Zinfandel plantings.', array['Established 1987 (27 CFR 9.110)', 'About 45,000 acres at establishment (Wine Institute, from the TTB final rule)', 'Contains Cienega Valley, Lime Kiln Valley and Paicines']::text[], 'PUBLISHED'
