-- united-states.california.central-coast.san-benito.cienega-valley
insert into public.wine_place_articles (wine_place_id, description, climate, soils, grape_varieties, wine_styles, key_facts, editorial_status)
select id, 'A valley south of Hollister in western San Benito County, below the Gabilan Range, with Pescadero Creek running through its vineyards and the San Andreas fault dividing its floor. It holds some of the oldest continuously producing vineyards in California, including head-trained Zinfandel from 1906.', 'Moderate, sheltered by the mountains and cooled by Monterey Bay, about 20 miles away, with a daily afternoon breeze in summer.', 'Granite and limestone on the western side of the fault, granite and sandstone on the eastern side.', 'Old-vine Zinfandel and Pinot Noir, with Chardonnay.', 'Dry red wines from old-vine Zinfandel and Pinot Noir, and dry Chardonnay.', array['Established 1982 (27 CFR 9.38)', 'The San Andreas fault divides the valley floor (Please the Palate)', 'Contains the Lime Kiln Valley AVA']::text[], 'PUBLISHED'
