-- united-states.california.central-coast.san-benito.cienega-valley.lime-kiln-valley
insert into public.wine_place_articles (wine_place_id, description, climate, soils, grape_varieties, wine_styles, key_facts, editorial_status)
select id, 'A very small AVA of about 2,300 acres at the southern end of the Cienega Valley, named after the lime kilns once worked on its limestone. Its Enz Vineyard, planted in 1923, is head-trained, dry-farmed and own-rooted.', 'Like the Cienega Valley around it: moderate, sheltered by the Gabilan Range, with Monterey Bay air in the afternoon.', 'A mix of granite and limestone-rich soils.', 'Mourvèdre and Zinfandel from old head-trained plantings.', 'Dry red wines from Zinfandel and Mourvèdre.', array['Established 1982 (27 CFR 9.27)', 'About 2,300 acres at establishment (Wine Institute, from the TTB final rule)', 'Lies within the Cienega Valley AVA']::text[], 'PUBLISHED'
