-- united-states.california.central-coast.san-francisco-bay.santa-clara-valley
insert into public.wine_place_articles (wine_place_id, description, climate, soils, grape_varieties, wine_styles, key_facts, editorial_status)
select id, 'A large AVA of about 339,200 acres around the southern end of San Francisco Bay, from San Jose and the Peninsula cities south to Morgan Hill and Gilroy. By the 1850s the valley had more vineyards than any other part of California, and Almaden, founded in 1852, began here. It holds Pacheco Pass and San Ysidro District.', 'Mediterranean, cooled by the bay in the north and by marine air through gaps in the Santa Cruz Mountains in the south.', 'Alluvial valley soils and hillside soils at the foot of the Santa Cruz Mountains and the Diablo Range.', 'Cabernet Sauvignon, Pinot Noir and Chardonnay lead, with Petite Sirah, Zinfandel, Syrah and Merlot.', 'Dry red and white wines from Cabernet Sauvignon, Pinot Noir and Chardonnay.', array['Established 1989 (27 CFR 9.126)', 'About 339,200 acres at establishment (Wine Institute, from the TTB final rule)', 'Almaden was founded here in 1852', 'Contains the Pacheco Pass and San Ysidro District AVAs']::text[], 'PUBLISHED'
  from public.wine_places where canonical_key = 'united-states.california.central-coast.san-francisco-bay.santa-clara-valley';
