-- united-states.california.central-coast.san-francisco-bay.santa-clara-valley.pacheco-pass
insert into public.wine_place_articles (wine_place_id, description, climate, soils, grape_varieties, wine_styles, key_facts, editorial_status)
select id, 'A very small AVA of about 3,200 acres near the Pacheco Pass highway on the Santa Clara–San Benito county line, east of Gilroy. Italian families from Calabria planted orchards and vines here more than a century ago; the Casa de Fruta roadside stop grew out of them.', 'Inland and warm, with some marine air reaching the pass from the Monterey Bay side.', 'Soils of the small valley floor and lower slopes along Pacheco Creek.', 'Zinfandel and Merlot, with Cabernet Sauvignon and Chardonnay.', 'Dry red wines from Zinfandel and Merlot, and some whites.', array['Established 1984 (27 CFR 9.88)', 'About 3,200 acres at establishment (Wine Institute, from the TTB final rule)', 'Lies within the Santa Clara Valley AVA']::text[], 'PUBLISHED'
