-- united-states.california.central-coast.york-mountain
insert into public.wine_place_articles (wine_place_id, description, climate, soils, grape_varieties, wine_styles, key_facts, editorial_status)
select id, 'A small, high AVA in the Santa Lucia Range west of Templeton, about seven miles from the Pacific at about 1,500 feet. Andrew York bought land here in 1882 and founded the winery that became York Mountain Winery, kept by his family until 1970. It lies next to Paso Robles but is a separate, older AVA.', 'Cooled by daily coastal winds and a regular fog layer: markedly cooler and wetter than the Paso Robles country to the east.', 'Mountain soils on steep slopes of the Santa Lucia Range.', 'Pinot Noir and Zinfandel, with Syrah, Grenache and Cabernet Sauvignon.', 'Dry red wines from Pinot Noir, Zinfandel and Rhône varieties.', array['Established 1983 (27 CFR 9.80)', 'About seven miles from the Pacific at about 1,500 feet (Epoch Estate Wines)', 'Andrew York bought his homestead here in 1882 (Epoch Estate Wines)']::text[], 'PUBLISHED'
  from public.wine_places where canonical_key = 'united-states.california.central-coast.york-mountain';
