-- united-states.california.central-valley.capay-valley
insert into public.wine_place_articles (wine_place_id, description, climate, soils, grape_varieties, wine_styles, key_facts, editorial_status)
select id, 'A long valley of about 102,400 acres, some 150 square miles, in northwestern Yolo County along Cache Creek, bordering Napa, Lake and Colusa counties. "Capay" comes from the Wintun word for "stream". Only about 25 acres were planted when it was proposed; hillside vineyards such as Casey Flat Ranch, at about 2,000 feet, have been added since.', 'Long, warm growing days with wide day-to-night swings, and harvest earlier than in Napa Valley.', 'Sandy to rocky soils over fractured sandstone on the hillsides, and alluvial soils along Cache Creek.', 'Syrah and Cabernet Sauvignon, with Cabernet Franc, Mourvèdre, Viognier and Sauvignon Blanc.', 'Dry red wines from Bordeaux and Rhône varieties, dry whites and rosé.', array['Established 2002 (27 CFR 9.176)', 'About 102,400 acres at establishment (Wine Institute, from the TTB final rule)', 'About 25 acres planted when proposed (Wine Spectator)']::text[], 'PUBLISHED'
  from public.wine_places where canonical_key = 'united-states.california.central-valley.capay-valley';
