-- united-states.california.central-valley.clarksburg
insert into public.wine_place_articles (wine_place_id, description, climate, soils, grape_varieties, wine_styles, key_facts, editorial_status)
select id, 'Flat farmland along the Sacramento River in the Delta, south of Sacramento, across Sacramento, Solano and Yolo counties. The AVA was about 64,640 acres until 2022, when about 27,945 acres on Grand Island and Ryer Island were added. It is known above all for Chenin Blanc, and it holds Merritt Island.', 'Warm days and cool nights: the "Delta breeze" brings cold air and fog from San Francisco Bay up the river channels in the evening; about 16 inches of rain a year.', 'Poorly drained clay and clay loam soils of the Delta''s alluvial fans, basins and flood plains, from about 10 feet below to 5 feet above sea level.', 'Chenin Blanc stands out, with Petite Sirah, Chardonnay and Pinot Gris.', 'Dry and off-dry Chenin Blanc, and red wines from Petite Sirah.', array['Established 1984 (27 CFR 9.95)', 'About 64,640 acres, expanded by about 27,945 acres in 2022 (T.D. TTB-178)', 'Contains the Merritt Island AVA']::text[], 'PUBLISHED'
  from public.wine_places where canonical_key = 'united-states.california.central-valley.clarksburg';
