-- united-states.california.central-valley.clarksburg.merritt-island
insert into public.wine_place_articles (wine_place_id, description, climate, soils, grape_varieties, wine_styles, key_facts, editorial_status)
select id, 'An island of about 5,000 acres in the Sacramento River Delta in Yolo County, about six miles south of Sacramento, within the Clarksburg AVA. It was petitioned by Bogle Vineyards; commercial grape-growing began in 1969, and Chenin Blanc was its principal grape.', 'Cool evenings and fog from San Francisco Bay reach the island along the Delta channels.', 'Fertile, rich loams of the Delta island.', 'Chenin Blanc was the principal grape among eight varieties grown.', 'Dry and off-dry Chenin Blanc, and other whites.', array['Established 1983 (27 CFR 9.68)', 'About 5,000 acres at establishment (Wine Institute, from the TTB final rule)', 'Lies within the Clarksburg AVA']::text[], 'PUBLISHED'
