-- united-states.california.central-valley.diablo-grande
insert into public.wine_place_articles (wine_place_id, description, climate, soils, grape_varieties, wine_styles, key_facts, editorial_status)
select id, 'An area of about 30,000 acres in the Diablo Range in western Stanislaus County, west of Patterson, named after the resort community and Mount Diablo. When it was established in 1998 about 35 acres were planted, at 1,000 to 1,800 feet, the highest vineyards in Stanislaus County.', 'Warmer than Modesto but cooler than Newman, Tracy and Westley, above the fog belt of the lower land, with 14 to 23% more rain than the areas around it.', 'Residual soils from sandstone, such as Arburua loam, Wisflat sandy loam and Contra Costa clay loam, unlike the alluvial soils below.', 'Merlot and Chardonnay, with other varieties in small plantings.', 'Dry Merlot and Chardonnay from hillside vineyards.', array['Established 1998 (27 CFR 9.156)', 'About 30,000 acres; about 35 acres planted at establishment (T.D. ATF-399)', 'Vineyards at 1,000 to 1,800 feet (T.D. ATF-399)']::text[], 'PUBLISHED'
