-- united-states.california.central-valley.dunnigan-hills
insert into public.wine_place_articles (wine_place_id, description, climate, soils, grape_varieties, wine_styles, key_facts, editorial_status)
select id, 'Gently rolling hills of about 89,000 acres in northwestern Yolo County, on the west side of the Sacramento Valley. R.H. Phillips, whose vineyard grew to about 1,500 acres, was its pioneering winery.', 'Mediterranean and hot, but good air drainage lowers the risk of spring frost and gives cooler summers than the valley floor.', 'Soils of low rolling hills on the valley''s western edge.', 'Chardonnay and Syrah, with other French and Rhône varieties.', 'Dry Chardonnay and red wines from Syrah and other Rhône varieties.', array['Established 1993 (27 CFR 9.145)', 'About 89,000 acres at establishment (Wine Institute, from the TTB final rule)', 'R.H. Phillips''s vineyard grew to about 1,500 acres (Beverage Tasting Institute)']::text[], 'PUBLISHED'
