-- united-states.california.central-valley.madera
insert into public.wine_place_articles (wine_place_id, description, climate, soils, grape_varieties, wine_styles, key_facts, editorial_status)
select id, 'A large AVA of about 448,000 acres in the hot, irrigated San Joaquin Valley across Madera and Fresno counties. It is known above all for dessert and fortified wines: Quady, founded in Madera in 1975, makes Muscat dessert wines and a port-style wine here.', 'Hot, dry and irrigated, typical of the central San Joaquin Valley.', 'Deep alluvial soils of the San Joaquin Valley floor.', 'Muscat varieties and Zinfandel, with Chenin Blanc and Portuguese varieties for port-style wines.', 'Sweet Muscat dessert wines, port-style fortified wines, and dry table wines.', array['Established 1984 (27 CFR 9.92)', 'About 448,000 acres at establishment (Wine Institute, from the TTB final rule)', 'Quady Winery was founded in Madera in 1975 (Quady)']::text[], 'PUBLISHED'
