-- united-states.california.central-valley.paulsell-valley
insert into public.wine_place_articles (wine_place_id, description, climate, soils, grape_varieties, wine_styles, key_facts, editorial_status)
select id, 'An AVA of about 34,155 acres of rolling hills in eastern Stanislaus County, between Knights Ferry and the Modesto Reservoir, from 140 to 612 feet. At establishment three commercial vineyards covered about 826 acres, with a fourth of 700 acres planned.', 'Warm, dry and inland: 4,201 to 5,204 growing degree days a year (2012-2017), with growing-season lows of about 55 to 58 °F.', 'Mostly from volcanic tuff, the Pentz and Peters series, well drained, on mound-and-swale ground cut by arroyos.', 'Cabernet Sauvignon, Petit Verdot and Petite Sirah lead.', 'Dry red wines from Cabernet Sauvignon and Bordeaux varieties.', array['Established 2022 (27 CFR 9.285)', 'About 34,155 acres (T.D. TTB-181)', 'Three vineyards on about 826 acres at establishment (T.D. TTB-181)']::text[], 'PUBLISHED'
  from public.wine_places where canonical_key = 'united-states.california.central-valley.paulsell-valley';
