-- united-states.california.central-valley.river-junction
insert into public.wine_place_articles (wine_place_id, description, climate, soils, grape_varieties, wine_styles, key_facts, editorial_status)
select id, 'A very small AVA of about 1,300 acres in southern San Joaquin County, west of Modesto, where the Stanislaus River meets the San Joaquin. It has a single producer, McManis Family Vineyards, whose petition created it, and it grows Chardonnay.', 'The river basin stays a few degrees cooler than the farmland around it.', 'Alluvial flood-plain soils and sandy loams near the rivers.', 'Chardonnay, from the McManis estate vineyard.', 'Dry Chardonnay from a single estate vineyard.', array['Established 2001 (27 CFR 9.164)', 'About 1,300 acres at establishment (Wine Institute, from the TTB final rule)', 'A single producer, McManis Family Vineyards (McManis)']::text[], 'PUBLISHED'
