-- united-states.california.central-valley.salado-creek
insert into public.wine_place_articles (wine_place_id, description, climate, soils, grape_varieties, wine_styles, key_facts, editorial_status)
select id, 'A very small AVA of about 2,940 acres in western Stanislaus County, southwest of Patterson, on the edge of the Central Valley below the Diablo Range. At establishment a single vineyard had 44 acres of grapes.', 'Warm and inland: the Diablo Range to the west shields it from marine air; rainfall averages about 13 inches.', 'Fine sandy loam over deep loam subsoil, from sandstone and shale.', 'Cabernet Sauvignon, with Chardonnay and Tempranillo.', 'Dry red wines from Cabernet Sauvignon and some whites.', array['Established 2004 (27 CFR 9.163)', 'About 2,940 acres at establishment (Wine Institute, from the TTB final rule)', 'Southwest of Patterson, below the Diablo Range']::text[], 'PUBLISHED'
