-- united-states.california.central-valley.tracy-hills
insert into public.wine_place_articles (wine_place_id, description, climate, soils, grape_varieties, wine_styles, key_facts, editorial_status)
select id, 'An AVA of about 39,200 acres on east-sloping land between the San Joaquin Valley floor and the Diablo Range foothills, south and southwest of Tracy, across San Joaquin and Stanislaus counties. At establishment it had about 1,005 acres of vineyards, from 100 to 500 feet. It was first proposed as "Mt. Oso".', 'Dry: it lies in the rain shadow of Mt. Oso, with about 8 to 9 inches of rain, less fog, dew, frost and hail than around it, and about 4,033 degree days.', 'Alluvial soils washed down from the Diablo Range, unlike the sedimentary mountain soils above and the heavy clays to the east.', 'Cabernet Sauvignon and Syrah, with Chardonnay.', 'Dry red wines from Cabernet Sauvignon and Syrah, and some Chardonnay.', array['Established 2006 (27 CFR 9.204)', 'About 39,200 acres with about 1,005 acres of vineyards (TTB final rule, 2006)', 'Rainfall about 8 to 9 inches a year (TTB proposed rule, 2005)']::text[], 'PUBLISHED'
