-- united-states.california.central-valley.winters-highlands
insert into public.wine_place_articles (wine_place_id, description, climate, soils, grape_varieties, wine_styles, key_facts, editorial_status)
select id, 'An AVA of about 7,296 acres on the inner slope of the Coast Ranges west of Winters, across Solano and Yolo counties, where Putah Creek flows through the Berryessa Gap. At establishment about 134 acres were planted and three wineries worked there, Berryessa Gap Vineyards among them.', 'More growing degree days than the areas around it, with lower humidity and cooler evenings as Pacific air comes through the Berryessa Gap.', 'Fine clay and loamy alfisols and inceptisols, well drained, on gentle to steep slopes: gravelly loam over dark red clay.', 'Petite Sirah, Tempranillo and Syrah, with Zinfandel, Albariño and Sauvignon Blanc.', 'Dry red wines from Petite Sirah, Tempranillo and Syrah, and dry whites.', array['Established 2023 (27 CFR 9.290)', 'About 7,296 acres; about 134 acres planted at establishment (T.D. TTB-189)', 'Spans Solano and Yolo counties']::text[], 'PUBLISHED'
  from public.wine_places where canonical_key = 'united-states.california.central-valley.winters-highlands';
