-- united-states.california.covelo
insert into public.wine_place_articles (wine_place_id, description, climate, soils, grape_varieties, wine_styles, key_facts, editorial_status)
select id, 'A bowl-shaped basin of about 38,000 acres in northern Mendocino County, taking in Round Valley and Williams Valley around the town of Covelo, about 150 miles north of San Francisco. Its floor lies at 1,310 to 1,480 feet. Only about 2 acres were planted when it was established.', 'About 3,000 degree days (Region 3), roughly 125 frost-free days, about 40 inches of rain, the most in northern Mendocino County, and occasional snow.', 'Neutral to alkaline Feliz-Russian-Cole loams on the deep, level valley floor, unlike the acidic soils of the surrounding hills.', 'Pinot Noir and Chardonnay, the varieties the petition named as suited to its short season.', 'Dry red and white wines from a few small vineyards.', array['Established 2006 (27 CFR 9.187)', 'About 38,000 acres (TTB final rule)', 'Valley floor at 1,310 to 1,480 feet (TTB final rule)']::text[], 'PUBLISHED'
  from public.wine_places where canonical_key = 'united-states.california.covelo';
