-- united-states.california.cucamonga-valley
insert into public.wine_place_articles (wine_place_id, description, climate, soils, grape_varieties, wine_styles, key_facts, editorial_status)
select id, 'An AVA of about 109,400 acres in San Bernardino and Riverside counties, east of Los Angeles, once one of California''s largest wine regions. Secondo Guasti founded the Italian Vineyard Company here in 1900, and in the 1940s the valley had about 40,000 acres of grapes; fewer than 1,200 remain among houses and malls, many of them old, dry-farmed vines.', 'Warm to hot, suited to heat-loving varieties.', 'Deep sand or hardpan clay that restricts the old dry-farmed vines.', 'Zinfandel above all, with Grenache, Mourvèdre, Carignan and Palomino among old plantings.', 'Dry red wines from old-vine Zinfandel and Rhône varieties.', array['Established 1995 (27 CFR 9.150)', 'About 109,400 acres at establishment (Wine Institute, from the TTB final rule)', 'About 40,000 acres of grapes in the 1940s, under 1,200 today (Wine Spectator)']::text[], 'PUBLISHED'
