-- united-states.california.dos-rios
insert into public.wine_place_articles (wine_place_id, description, climate, soils, grape_varieties, wine_styles, key_facts, editorial_status)
select id, 'A canyon of about 15,500 acres in northern Mendocino County where the Eel River meets its Middle Fork, about 12 miles long and 4 wide. "Dos Rios" is Spanish for "two rivers". Only about six acres of vines were planted at establishment.', 'Average temperatures of 52 to 58 °F and 30 to 60 inches of rain, mostly October to April; marine winds moderate the heat and the rivers reflect extra sunlight into the canyon.', 'Well-drained to excessively drained loams, sandy loams and gravelly loams from sandstone and siltstone, on canyon walls sloping 30 to 75 percent.', 'Zinfandel, with Cabernet Sauvignon, Merlot and Chardonnay.', 'Dry red wines from a few small vineyards.', array['Established 2005 (27 CFR 9.175)', 'About 15,500 acres; about six acres planted at establishment (TTB final rule)', 'Its upper edge is the 2,000-foot contour line (TTB final rule)']::text[], 'PUBLISHED'
  from public.wine_places where canonical_key = 'united-states.california.dos-rios';
