-- united-states.california.inwood-valley
insert into public.wine_place_articles (wine_place_id, description, climate, soils, grape_varieties, wine_styles, key_facts, editorial_status)
select id, 'An AVA of about 28,441 acres in the foothills east of Redding in Shasta County, below Blue Mountain, covering land between 1,000 and 3,000 feet. At establishment five vineyards covered about 62.5 acres. Merlot was planted at the Inwood Ranch in the late 1970s, and wild Mission vines survive from plantings of 1864.', 'Regions II to III, about 2,700 to 3,400 growing degree days, with about 57 inches of rain a year, 14 of them in the growing season.', 'Some 27 soil series, the Aiken series nearly a quarter of the area.', 'Merlot is the variety the rulemaking records, first planted at the Inwood Ranch in the late 1970s.', 'Dry red wines from a few small foothill vineyards.', array['Established 2012 (27 CFR 9.226)', 'About 28,441 acres; five vineyards on about 62.5 acres at establishment (TTB final rule)', 'Only land between 1,000 and 3,000 feet is included (TTB proposed rule, 2011)']::text[], 'PUBLISHED'
  from public.wine_places where canonical_key = 'united-states.california.inwood-valley';
insert into public.wine_place_styles (wine_place_id, style, sort_order, editorial_status)
