 where p.canonical_key = 'united-states.california.inwood-valley' and g.name = 'Merlot';

-- united-states.california.leona-valley
insert into public.wine_place_articles (wine_place_id, description, climate, soils, grape_varieties, wine_styles, key_facts, editorial_status)
select id, 'A narrow valley of about 13.4 square miles in northern Los Angeles County, formed along the San Andreas fault below the Angeles National Forest, with a floor from 2,932 to 3,800 feet. It is named after the early rancher Miguel Leonis. Zinfandel and Mission were planted in the early 1900s; about 20 acres were in production at establishment.', 'About 4,060 degree days (low Region V), 9 to 12 inches of rain, warm days and cool nights, and cold air draining off the slopes that protects against spring frost.', 'Very deep, well-drained soils of the Hanford-Ramona-Greenfield association on alluvial fans, from loamy sand to loam.', 'Pinot Noir today, after early Zinfandel and Mission plantings.', 'Dry red wines from a small area of vines.', array['Established 2008 (27 CFR 9.212)', 'About 13.4 square miles; about 20 acres in production at establishment (T.D. TTB-71)', 'Named after the rancher Miguel Leonis (T.D. TTB-71)']::text[], 'PUBLISHED'
  from public.wine_places where canonical_key = 'united-states.california.leona-valley';
