-- united-states.california.malibu-coast
insert into public.wine_place_articles (wine_place_id, description, climate, soils, grape_varieties, wine_styles, key_facts, editorial_status)
select id, 'An AVA of about 44,590 acres in the Santa Monica Mountains of Los Angeles and Ventura counties, above the Malibu coast. At establishment 52 small vineyards covered about 198 acres. It holds Malibu-Newton Canyon and Saddle Rock-Malibu.', 'Warm, with marine fog coming in from the Pacific over steep mountains, valleys and canyons.', 'Well-drained soils containing volcanic material.', 'Cabernet Sauvignon, Merlot and Syrah, with Chardonnay and Sauvignon Blanc.', 'Dry red wines from Bordeaux varieties and Syrah, and some whites.', array['Established 2014 (27 CFR 9.235)', 'About 44,590 acres; 52 vineyards on about 198 acres at establishment (T.D. TTB-121)', 'Contains Malibu-Newton Canyon and Saddle Rock-Malibu']::text[], 'PUBLISHED'
