-- united-states.california.malibu-coast.malibu-newton-canyon
insert into public.wine_place_articles (wine_place_id, description, climate, soils, grape_varieties, wine_styles, key_facts, editorial_status)
select id, 'A very small AVA of about 850 acres in the Santa Monica Mountains, a valley sheltered from the marine fog, within the Malibu Coast AVA. George Rosenthal planted Malibu''s first vineyard here in 1987, at about 1,450 feet and within four miles of the ocean.', 'Warmer than the surrounding Malibu Coast because the valley is sheltered from the marine fog, with cool breezes and plenty of sun; about 4,000 to 4,100 degree days.', 'Well-drained soils with volcanic material, shared with the wider Malibu Coast.', 'Cabernet Sauvignon, Cabernet Franc and Merlot, with Petit Verdot, Syrah, Viognier and Chardonnay.', 'Dry red wines from Bordeaux varieties, and some whites.', array['Established 1996 (27 CFR 9.152)', 'About 850 acres at establishment (Wine Institute, from the TTB final rule)', 'First planted in 1987, at about 1,450 feet (Rosenthal Estate Wines)']::text[], 'PUBLISHED'
  from public.wine_places where canonical_key = 'united-states.california.malibu-coast.malibu-newton-canyon';
