-- united-states.california.malibu-coast.saddle-rock-malibu
insert into public.wine_place_articles (wine_place_id, description, climate, soils, grape_varieties, wine_styles, key_facts, editorial_status)
select id, 'A small, raised valley of about 2,090 acres on the leeward side of the Santa Monica Mountains, about 32 miles west of downtown Los Angeles, from 1,700 to 2,236 feet. It is named after the Saddle Rock formation; the Semler family''s Saddlerock Ranch vineyard, planted from 1992, was the only producer when it was established.', 'About 4,200 degree days, warmer than Malibu-Newton Canyon: the height, north-facing slopes and leeward position limit the marine cooling.', 'Cropley clay, Gilroy clay loam and Hambright loam, deeper and with more clay than neighbouring areas.', 'Cabernet Sauvignon, Merlot and Syrah, with Sauvignon Blanc.', 'Dry red wines from Cabernet Sauvignon, Merlot and Syrah.', array['Established 2006 (27 CFR 9.203)', 'About 2,090 acres; 70 acres producing in 2005 (T.D. TTB-52)', 'Elevations from 1,700 to 2,236 feet (T.D. TTB-52)']::text[], 'PUBLISHED'
