-- united-states.california.manton-valley
insert into public.wine_place_articles (wine_place_id, description, climate, soils, grape_varieties, wine_styles, key_facts, editorial_status)
select id, 'A stream-cut valley of about 11,178 acres in the foothills of Mount Lassen, east of Redding, across the Shasta–Tehama county line, from about 2,000 to 3,500 feet. Nights fall far lower than in the surrounding lowlands.', 'Region III, while Redding and Chico nearby are Region V; the average day-to-night swing is about 38 °F at the height of the season.', 'Soils of a flat to gently rolling valley floor and slopes cut by streams off Mount Lassen.', 'Syrah and Petite Sirah, with Cabernet Sauvignon, Merlot and Zinfandel.', 'Dry red wines from Syrah, Petite Sirah and Bordeaux varieties.', array['Established 2014 (27 CFR 9.236)', 'About 11,178 acres at establishment (Wine Institute, from the TTB final rule)', 'Spans Shasta and Tehama counties']::text[], 'PUBLISHED'
