-- united-states.california.north-coast.benmore-valley
insert into public.wine_place_articles (wine_place_id, description, climate, soils, grape_varieties, wine_styles, key_facts, editorial_status)
select id, 'A small, high valley of about 1,440 acres in southwestern Lake County, at about 2,400 feet among mountains averaging 2,800 feet. Its only commercial vineyard was the Trione family''s Chardonnay, grown for Geyser Peak; the harsh climate defeated it, most vines were removed, and the valley is now mainly grazing land. It is named after Benjamin Logan Moore, a 19th-century cattle rustler.', 'Cold for California: the growing season starts late, the average last frost comes in late May, and frost has been recorded as late as the Fourth of July.', 'Soils of an enclosed mountain valley floor and its surrounding slopes.', 'Chardonnay was the only grape grown commercially here.', 'Dry white wine from Chardonnay, when the vineyard was farmed.', array['Established 1991 (27 CFR 9.138)', 'About 1,440 acres at about 2,400 feet (Lake County News)', 'Named after Benjamin Logan Moore (Lake County News)']::text[], 'PUBLISHED'
  from public.wine_places where canonical_key = 'united-states.california.north-coast.benmore-valley';
