-- united-states.california.north-coast.clear-lake.big-valley-district-lake-county
insert into public.wine_place_articles (wine_place_id, description, climate, soils, grape_varieties, wine_styles, key_facts, editorial_status)
select id, 'The flat valley floor south of Clear Lake around Kelseyville and Finley, about 11,000 acres between about 1,300 and 1,550 feet. At establishment it had 43 vineyards with about 1,800 acres of grapes and six wineries, and it holds most of Lake County''s Sauvignon Blanc.', 'Lakeside and high, at about 1,300 to 1,550 feet, with Clear Lake moderating temperatures.', 'Mostly alluvial soils laid down on the lake''s old floodplain, with seams of gravel.', 'Sauvignon Blanc above all, with Cabernet Sauvignon, Zinfandel, Cabernet Franc and Chardonnay.', 'Dry Sauvignon Blanc and red wines from Cabernet Sauvignon and Zinfandel.', array['Established 2013 (27 CFR 9.232)', 'About 11,000 acres (TTB final rule)', '43 vineyards with about 1,800 acres of grapes at establishment (TTB final rule)', 'Lies within the Clear Lake AVA']::text[], 'PUBLISHED'
