-- united-states.california.north-coast.clear-lake.kelsey-bench-lake-county
insert into public.wine_place_articles (wine_place_id, description, climate, soils, grape_varieties, wine_styles, key_facts, editorial_status)
select id, 'A bench of about 9,100 acres west of Kelseyville, between the volcanic mountains around Mount Konocti and the flat Big Valley below, from about 1,400 to 1,775 feet. At establishment it had 27 vineyards with about 900 acres of grapes and one winery.', 'High and inland, with warm days and cool nights, between the volcanic uplands and the lake plain.', 'Once a pyroclastic flow, the bench is a transition from volcanic mountains to alluvial plain: rocky volcanic soils with good drainage, giving smaller crops.', 'Cabernet Sauvignon and Zinfandel, with Cabernet Franc, Sauvignon Blanc and Merlot.', 'Dry red wines from Cabernet Sauvignon, Zinfandel and Cabernet Franc, and some whites.', array['Established 2013 (27 CFR 9.233)', 'About 9,100 acres (TTB final rule)', '27 vineyards with about 900 acres of grapes at establishment (TTB final rule)', 'Lies within the Clear Lake AVA']::text[], 'PUBLISHED'
