-- united-states.california.north-coast.clear-lake.upper-lake-valley
insert into public.wine_place_articles (wine_place_id, description, climate, soils, grape_varieties, wine_styles, key_facts, editorial_status)
select id, 'A valley of about 17,360 acres at the north end of Clear Lake around the town of Upper Lake, between 1,300 and 1,800 feet. At establishment it had 16 commercial vineyards on about 300 acres. The same rule moved the Clear Lake boundary so that it lies wholly within it.', 'About 3,158 growing degree days (median), about 202 frost-free days and 35 to 43 inches of rain a year; constant gentle winds keep canopies cool and dry.', 'Moderately deep loams on the hills, deep loams on the valley floor, and poorly drained silty clay loams, over a shallow, calcium-rich groundwater basin.', 'Sauvignon Blanc, the grape the rule names, with Cabernet Sauvignon.', 'Dry Sauvignon Blanc and some red wine from Cabernet Sauvignon.', array['Established 2022 (27 CFR 9.286)', 'About 17,360 acres; 16 vineyards on about 300 acres at establishment (TTB final rule)', 'Rainfall 35 to 43 inches a year (TTB final rule)', 'Lies within the Clear Lake AVA']::text[], 'PUBLISHED'
  from public.wine_places where canonical_key = 'united-states.california.north-coast.clear-lake.upper-lake-valley';
