-- united-states.california.north-coast.cole-ranch
insert into public.wine_place_articles (wine_place_id, description, climate, soils, grape_varieties, wine_styles, key_facts, editorial_status)
select id, 'A very small AVA, about 150 acres on a single ranch in the hills between Ukiah and Boonville in Mendocino County, at about 1,400 to 1,600 feet. Its vineyard grows Cabernet Sauvignon, Riesling, Pinot Noir and Merlot.', 'An upland climate at about 1,400 to 1,600 feet, in the hills between the coast and the warm inland valleys.', 'Upland soils on the ranch''s slopes and small valley floor.', 'Cabernet Sauvignon and Riesling, with Pinot Noir and Merlot.', 'Dry red wines from Cabernet Sauvignon and Merlot, and Riesling.', array['Established 1983 (27 CFR 9.42)', 'About 150 acres at establishment (Wine Institute, from the TTB final rule)', 'A single ranch between Ukiah and Boonville']::text[], 'PUBLISHED'
