-- united-states.california.north-coast.eagle-peak-mendocino-county
insert into public.wine_place_articles (wine_place_id, description, climate, soils, grape_varieties, wine_styles, key_facts, editorial_status)
select id, 'A mountainous AVA of about 26,260 acres in Mendocino County, west of Redwood Valley, named after the Eagle Peak summit. At establishment about 120 acres were planted in 16 vineyards, mostly Pinot Noir; Masút, farmed by the Fetzer brothers, is among them.', 'Cool growing-season temperatures with a marine influence and strong breezes.', 'Shallow soils with little water-holding capacity on steep slopes, unlike the deep alluvial soils of the valleys around it.', 'Pinot Noir dominates the small planted area.', 'Dry Pinot Noir from steep mountain vineyards.', array['Established 2014 (27 CFR 9.237)', 'About 26,260 acres (T.D. TTB-124)', 'About 120 acres in 16 vineyards at establishment (T.D. TTB-124)']::text[], 'PUBLISHED'
  from public.wine_places where canonical_key = 'united-states.california.north-coast.eagle-peak-mendocino-county';
