 where p.canonical_key = 'united-states.california.north-coast.eagle-peak-mendocino-county' and g.name = 'Pinot Noir';

-- united-states.california.north-coast.guenoc-valley
insert into public.wine_place_articles (wine_place_id, description, climate, soils, grape_varieties, wine_styles, key_facts, editorial_status)
select id, 'A valley of about 4,396 acres in southern Lake County, one of the earliest AVAs. The actress Lillie Langtry bought the Guenoc ranch in 1888 to make claret-style wine, and the estate still farms Cabernet Sauvignon and the other Bordeaux varieties.', 'A rain-shadowed inland valley shut off by rocky ridges, with warm days and cool nights.', 'Soils of the valley floor and the rocky ridges around it.', 'Cabernet Sauvignon and the other Bordeaux varieties, with Sauvignon Blanc.', 'Dry red wines from Cabernet Sauvignon and Bordeaux blends, and dry whites.', array['Established 1981 (27 CFR 9.26)', 'About 4,396 acres at establishment (Wine Institute, from the TTB final rule)', 'Lillie Langtry bought the Guenoc ranch in 1888 (The Seattle Times)']::text[], 'PUBLISHED'
