-- united-states.california.north-coast.high-valley
insert into public.wine_place_articles (wine_place_id, description, climate, soils, grape_varieties, wine_styles, key_facts, editorial_status)
select id, 'An enclosed, bowl-shaped valley of about 14,000 acres above the eastern shore of Clear Lake near Clearlake Oaks, running east to west, which is unusual in the Coast Ranges. Its floor lies at 1,700 to 1,800 feet and the AVA reaches 3,000 feet. About 1,000 acres were planted at establishment.', 'Region 2–3, one of the cooler parts of Lake County: winds from the Clear Lake basin blow through the valley, frost can come into June, and rain varies from about 18 to 35 inches.', 'Weathered volcanic residue and Franciscan sandstone and shale: Wolfcreek loam on the valley floor, Millsholm and Hopland series on the ridges.', 'Cabernet Sauvignon and Sauvignon Blanc, with Syrah, Zinfandel, Merlot and Petite Sirah.', 'Dry red wines from Cabernet Sauvignon and Syrah, and dry Sauvignon Blanc.', array['Established 2005 (27 CFR 9.189)', 'About 14,000 acres, about 1,000 planted at establishment (T.D. TTB-30)', 'Elevations from 1,600 to 3,000 feet (T.D. TTB-30)']::text[], 'PUBLISHED'
