-- united-states.california.north-coast.long-valley-lake-county
insert into public.wine_place_articles (wine_place_id, description, climate, soils, grape_varieties, wine_styles, key_facts, editorial_status)
select id, 'A long, narrow valley of about 7,605 acres in eastern Lake County, with a floor at about 1,322 feet and foothills rising 200 to 500 feet more. At establishment it had five vineyards on about 149 acres and three wineries; the same rule extended High Valley to meet it.', 'Region III, about 3,378 growing degree days: wind through the valley cools the vines, and cold air draining off the foothills protects them from late spring frost; 27 to 33 inches of rain.', 'Soils of the Cache Formation: tuffaceous and diatomaceous sands and silts, limestone, gravel and volcanic rocks.', 'Cabernet Sauvignon, Cabernet Franc, Petite Sirah and Syrah.', 'Dry red wines from Cabernet Sauvignon, Cabernet Franc, Petite Sirah and Syrah.', array['Established 2023 (27 CFR 9.289)', 'About 7,605 acres (T.D. TTB-188)', 'Five vineyards on about 149 acres and three wineries at establishment (T.D. TTB-188)']::text[], 'PUBLISHED'
