-- united-states.california.north-coast.mendocino.mcdowell-valley
insert into public.wine_place_articles (wine_place_id, description, climate, soils, grape_varieties, wine_styles, key_facts, editorial_status)
select id, 'A small valley east of Hopland in Mendocino County, ringed by mountains, known for some of the oldest Syrah and Grenache in California. The first varietal Syrah released in California came from these vines, from the 1978 vintage. Cold air gathers on the valley floor at night.', 'Warm days and cool nights: cold air collects on the enclosed valley floor after dark, which keeps acidity in the grapes.', 'Soils of the valley floor and benches, dry-farmed in the old blocks.', 'Syrah and Grenache, with Petite Sirah, in old head-trained, dry-farmed blocks.', 'Dry red wines from Syrah and Grenache, and dry rosé.', array['Established 1981 (27 CFR 9.36)', 'California''s first varietal Syrah came from here, the 1978 vintage (Historic Vineyard Society)', 'Lies within the Mendocino AVA']::text[], 'PUBLISHED'
  from public.wine_places where canonical_key = 'united-states.california.north-coast.mendocino.mcdowell-valley';
