-- united-states.california.north-coast.mendocino.potter-valley
insert into public.wine_place_articles (wine_place_id, description, climate, soils, grape_varieties, wine_styles, key_facts, editorial_status)
select id, 'A high valley of about 27,500 acres at the headwaters of the East Fork of the Russian River in Mendocino County, at about 1,000 feet, roughly twice the height of Ukiah. Guinness McFadden settled here in 1970 and began planting Riesling, now its signature grape.', 'Continental for Mendocino: days can reach 95 °F and nights fall to the 40s or low 50s; the height gives a shorter season, later budbreak and earlier frosts.', 'Soils of the upland valley floor at the river''s headwaters.', 'Riesling first, with Sauvignon Blanc, Pinot Noir, Pinot Gris and Gewürztraminer.', 'Dry and off-dry Riesling, dry Sauvignon Blanc and Pinot Noir.', array['Established 1983 (27 CFR 9.82)', 'About 27,500 acres at establishment (Wine Institute, from the TTB final rule)', 'At about 1,000 feet (Wine & Spirits Magazine)', 'Lies within the Mendocino AVA']::text[], 'PUBLISHED'
  from public.wine_places where canonical_key = 'united-states.california.north-coast.mendocino.potter-valley';
