-- united-states.california.north-coast.mendocino.redwood-valley
insert into public.wine_place_articles (wine_place_id, description, climate, soils, grape_varieties, wine_styles, key_facts, editorial_status)
select id, 'An upland valley of about 22,400 acres north of Ukiah in the east-central interior of Mendocino County. Italian immigrant families planted some of the county''s early vineyards here, and it is known for Zinfandel, Cabernet Sauvignon, Petite Sirah and Carignan.', 'Cooler than the surrounding inland areas because a gap in the coastal ridge lets Pacific air in; ripening is gradual.', 'Thin, rocky, iron-rich red soils on the valley floor and slopes.', 'Zinfandel and Cabernet Sauvignon, with Petite Sirah, Carignan and Barbera.', 'Dry red wines from Zinfandel, Cabernet Sauvignon and Petite Sirah.', array['Established 1996 (27 CFR 9.153)', 'About 22,400 acres at establishment (Wine Institute, from the TTB final rule)', 'Lies within the Mendocino AVA']::text[], 'PUBLISHED'
  from public.wine_places where canonical_key = 'united-states.california.north-coast.mendocino.redwood-valley';
