-- united-states.california.north-coast.mendocino.yorkville-highlands
insert into public.wine_place_articles (wine_place_id, description, climate, soils, grape_varieties, wine_styles, key_facts, editorial_status)
select id, 'A string of high benches and troughs along Highway 128 in southern Mendocino County, between Anderson Valley and Alexander Valley, following the headwaters of Dry Creek and Rancheria Creek. Of about 40,000 acres, some 70 were planted at establishment, almost entirely above 800 feet.', 'In between Anderson Valley and Alexander Valley: about 3,060 heat units against 2,500 and 3,650 there, with marine air more than half the growing season and about 50 inches of rain.', 'Rocky hill soils with gravel and old brittle rock, thinner than their neighbours'': Bearwallow, Hellman and Yorkville series.', 'Pinot Noir and Sauvignon Blanc, with Chardonnay and Syrah.', 'Dry Pinot Noir and Sauvignon Blanc, and some Syrah.', array['Established 1998 (27 CFR 9.159)', 'About 40,000 acres; about 70 planted at establishment (T.D. ATF-397)', 'The same rule extended the Mendocino AVA to take it in (T.D. ATF-397)']::text[], 'PUBLISHED'
