insert into public.wine_place_articles (wine_place_id, description, climate, soils, grape_varieties, wine_styles, key_facts, editorial_status)
select id, 'A small valley in southwestern Solano County, about four miles long and one mile wide, next to the Napa County line and west of Suisun Valley. It is not the Green Valley in Sonoma County. About 800 acres are planted, mostly to red grapes.', 'Maritime, moderated by nearby Suisun Bay.', 'Soils of the small valley floor and its surrounding slopes.', 'Cabernet Sauvignon, Zinfandel and Petite Sirah, with Sangiovese, Syrah and Merlot.', 'Dry red wines from Cabernet Sauvignon, Zinfandel and Petite Sirah.', array['Established 1982 (27 CFR 9.44)', 'About 2,560 acres at establishment (Wine Institute, from the TTB final rule)', 'About 800 acres planted (The Bubbly Professor)']::text[], 'PUBLISHED'
