insert into public.wine_place_articles (wine_place_id, description, climate, soils, grape_varieties, wine_styles, key_facts, editorial_status)
select id, 'A valley about 8 miles long and 3 miles wide in Solano County, east of Napa, of about 15,000 acres with some 3,000 planted. It was first known for Cabernet Sauvignon and Petite Sirah and now grows more than 20 varieties; just over a dozen wineries work here.', 'Region III, with marine air from the Pacific and San Pablo Bay flowing in; the southern end can be up to 14 °F cooler.', 'Soils of the valley floor and the surrounding foothills.', 'Cabernet Sauvignon and Petite Sirah, with Syrah, Zinfandel, Chardonnay and Sauvignon Blanc.', 'Dry red wines from Petite Sirah and Cabernet Sauvignon, and dry whites.', array['Established 1982 (27 CFR 9.45)', 'About 15,000 acres, some 3,000 planted (The Bubbly Professor)', 'Winkler Region III (The Bubbly Professor)']::text[], 'PUBLISHED'
