-- united-states.california.palos-verdes-peninsula
insert into public.wine_place_articles (wine_place_id, description, climate, soils, grape_varieties, wine_styles, key_facts, editorial_status)
select id, 'A coastal AVA of about 15,900 acres on the Palos Verdes Peninsula in southwestern Los Angeles County, a low mountain between the Los Angeles Plain and the Pacific, from sea level to about 1,460 feet at San Pedro Hill. Only about 7 acres of vines were planted at establishment.', 'Mediterranean and warm, with mild winters: average monthly highs of 63 to 74 °F, lows of 48 to 62 °F, and about 14 inches of rain.', 'Altamont clay adobe, Altamont clay loam and Diablo clay adobe, rich in clay and calcium.', 'Pinot Noir, Chardonnay, Merlot and Cabernet Sauvignon, the varieties the final rule names.', 'Dry red and white wines from a handful of small vineyards.', array['Established 2021 (27 CFR 9.274)', 'About 15,900 acres; about 7 acres planted at establishment (TTB final rule)', 'Elevations from sea level to about 1,460 feet (TTB final rule)']::text[], 'PUBLISHED'
