-- united-states.california.seiad-valley
insert into public.wine_place_articles (wine_place_id, description, climate, soils, grape_varieties, wine_styles, key_facts, editorial_status)
select id, 'A small valley of about 2,160 acres beside the Klamath River in Siskiyou County, about 15 miles south of the Oregon border, California''s northernmost AVA. It was established for a single grower, Seiad Valley Vineyards, which has since closed; about 2.5 acres were planted.', 'Hot summers and mild winters in a cool mountain valley, where rock tailings left by gold mining store the day''s heat and help against frost.', 'Deep alluvial loam, sand and clay on the valley floor, mixed with granite-rich mining tailings.', 'Riesling was the grape grown on the valley''s only vineyard.', 'White wine from Riesling, when the vineyard was farmed.', array['Established 1994 (27 CFR 9.148)', 'About 2,160 acres, with about 2.5 acres planted (ATF proposed rule, 1994)', 'Named after a valley trappers knew as "Sciad" before 1850 (ATF proposed rule, 1994)']::text[], 'PUBLISHED'
  from public.wine_places where canonical_key = 'united-states.california.seiad-valley';
insert into public.wine_place_styles (wine_place_id, style, sort_order, editorial_status)
