 where p.canonical_key = 'united-states.california.seiad-valley' and g.name = 'Riesling';

-- united-states.california.sierra-foothills.north-yuba
insert into public.wine_place_articles (wine_place_id, description, climate, soils, grape_varieties, wine_styles, key_facts, editorial_status)
select id, 'An AVA of about 22,400 acres in the Sierra Nevada foothills of Yuba County, around Oregon House, about 70 miles northeast of Sacramento. It was created for the Renaissance Vineyard, planted from 1971 on some 365 acres of terraces at about 2,000 feet; about 33 acres remain, farmed by a few small producers.', 'Foothill climate at about 2,000 to 2,250 feet, with different slopes suited to different varieties.', 'Decomposed granite, iron-rich and red, on steep terraced slopes.', 'Cabernet Sauvignon, Syrah and Riesling, with Sauvignon Blanc and Semillon.', 'Dry red wines, and dry and late-harvest Riesling.', array['Established 1985 (27 CFR 9.106)', 'About 22,400 acres at establishment (Wine Institute, from the TTB final rule)', 'Renaissance planted about 365 acres of terraces (San Francisco Chronicle)']::text[], 'PUBLISHED'
