-- united-states.california.sierra-pelona-valley
insert into public.wine_place_articles (wine_place_id, description, climate, soils, grape_varieties, wine_styles, key_facts, editorial_status)
select id, 'A valley of about 9.7 square miles in northern Los Angeles County, taking in Hauser Canyon, upper Agua Dulce Canyon and Mint Canyon, below the Sierra Pelona range, from 2,400 to 3,400 feet. About 96 acres were planted in 2008.', 'Summer highs up to 102 °F and nights of 50 to 60 °F, swings of 40 to 50 °F; 9 to 12 inches of rain, and winds that reduce frost and fungal disease.', 'Very deep, moderately drained valley soils with a high mineral content and low fertility.', 'Syrah, the grape the petition named as suited to the area.', 'Dry red wines, mainly Syrah, from a small planted area.', array['Established 2010 (27 CFR 9.218)', 'About 9.7 square miles; 96 acres of vines in 2008 (T.D. TTB-86)', 'Elevations from 2,400 to 3,400 feet (T.D. TTB-86)']::text[], 'PUBLISHED'
