-- united-states.california.south-coast.ramona-valley
insert into public.wine_place_articles (wine_place_id, description, climate, soils, grape_varieties, wine_styles, key_facts, editorial_status)
select id, 'An AVA of about 89,000 acres around the town of Ramona in central San Diego County, ringed by hills and mountains, from about 650 feet to over 3,000 feet. When it was established 17 vineyards grew about 45 acres; today it has the densest concentration of wineries in the county, more than 30.', 'Known locally as "the Valley of the Sun" for its lack of coastal fog: about 3,470 degree days, about 320 frost-free days and 16.5 inches of rain, with wide day-to-night swings.', 'Ramona, Visalia, Los Posas and Fallbrook loams, with nutrient-rich mafic rock on the mid-slopes.', 'Cabernet Sauvignon, Syrah and Tempranillo, with Sangiovese, Petite Sirah and Viognier.', 'Dry red wines from Bordeaux, Rhône, Spanish and Italian varieties.', array['Established 2005 (27 CFR 9.191)', 'About 89,000 acres; 17 vineyards on about 45 acres at establishment (T.D. TTB-39)', 'More than 30 active wineries (San Diego Tourism Authority)']::text[], 'PUBLISHED'
