-- united-states.california.south-coast.san-luis-rey
insert into public.wine_place_articles (wine_place_id, description, climate, soils, grape_varieties, wine_styles, key_facts, editorial_status)
select id, 'An AVA of about 97,700 acres around Fallbrook and Bonsall in northern San Diego County, following the lower San Luis Rey River. At establishment it had 44 vineyards on about 256 acres and 23 wineries.', 'Low and open to the ocean, mean elevation about 563 feet: cool marine air flows up the valley, giving milder summers than inland and fewer spring frosts; rainfall is low.', 'About 69% sandy loams and about half Alfisols, over decomposed granite.', 'Mediterranean varieties such as Grenache, Tempranillo, Sangiovese and Vermentino, with Bordeaux varieties.', 'Dry red and white wines from Mediterranean and Bordeaux varieties.', array['Established 2024 (27 CFR 9.295)', 'About 97,733 acres (T.D. TTB-195)', '44 vineyards on about 256 acres and 23 wineries at establishment (T.D. TTB-195)']::text[], 'PUBLISHED'
