-- united-states.california.south-coast.san-pasqual-valley
insert into public.wine_place_articles (wine_place_id, description, climate, soils, grape_varieties, wine_styles, key_facts, editorial_status)
select id, 'A valley of about 9,000 acres on the San Dieguito River near Escondido in San Diego County, among the earliest AVAs in California. Orfila Vineyards, founded in 1994, farms about 40 acres here.', 'Warm, dry days balanced by cool coastal breezes.', 'Soils of the San Dieguito River valley floor and its slopes.', 'Syrah, Sangiovese and Merlot, with Viognier.', 'Dry red wines from Rhône and Italian varieties, and some whites.', array['Established 1981 (27 CFR 9.25)', 'About 9,000 acres (San Diego County Vintners Association)', 'On the San Dieguito River near Escondido']::text[], 'PUBLISHED'
