-- united-states.california.squaw-valley-miramonte
insert into public.wine_place_articles (wine_place_id, description, climate, soils, grape_varieties, wine_styles, key_facts, editorial_status)
select id, 'An AVA of about 44,690 acres in the Sierra Nevada foothills of Fresno County, around Squaw Valley and Miramonte, from 1,600 to 3,500 feet. At establishment five small vineyards covered only about 7.5 acres, worked by hand on steep, boulder-strewn slopes.', 'Cooler days than the San Joaquin Valley below but warmer nights, thanks to cold-air drainage, and much more rain.', 'Granitic soils of the Vista, Sierra and Auberry series, well drained, with pH of 5.6 to 7.3.', 'Aglianico and Mourvèdre, with other red varieties in small plantings.', 'Dry red wines from a few estate vineyards.', array['Established 2015 (27 CFR 9.251)', 'About 44,690 acres; five vineyards on about 7.5 acres at establishment (T.D. TTB-129)', 'Elevations from 1,600 to 3,500 feet (T.D. TTB-129)']::text[], 'PUBLISHED'
