do $$
declare r record; n int;
begin
  -- Every row the data asked for is present. A grape name that failed to
  -- resolve would show up here as a short count rather than as silence.
  for r in
    select * from (values
    ('united-states.california.antelope-valley-of-the-california-high-desert', 1, 4, 1),
    ('united-states.california.central-coast.monterey.hames-valley', 1, 4, 1),
    ('united-states.california.central-coast.monterey.san-bernabe', 2, 6, 1),
    ('united-states.california.central-coast.monterey.san-lucas', 2, 4, 1),
    ('united-states.california.central-coast.san-antonio-valley', 1, 6, 1),
    ('united-states.california.central-coast.san-benito', 2, 5, 1),
    ('united-states.california.central-coast.san-benito.cienega-valley', 2, 3, 1),
    ('united-states.california.central-coast.san-benito.cienega-valley.lime-kiln-valley', 1, 2, 1),
    ('united-states.california.central-coast.san-benito.paicines', 2, 4, 1),
    ('united-states.california.central-coast.san-francisco-bay.lamorinda', 2, 4, 1),
    ('united-states.california.central-coast.san-francisco-bay.santa-clara-valley', 2, 6, 1),
    ('united-states.california.central-coast.san-francisco-bay.santa-clara-valley.pacheco-pass', 2, 4, 1),
    ('united-states.california.central-coast.san-francisco-bay.santa-clara-valley.san-ysidro-district', 2, 3, 1),
    ('united-states.california.central-coast.san-francisco-bay.santa-cruz-mountains.ben-lomond-mountain', 2, 5, 1),
    ('united-states.california.central-coast.york-mountain', 1, 5, 1),
    ('united-states.california.central-valley.capay-valley', 3, 6, 1),
    ('united-states.california.central-valley.clarksburg', 2, 4, 1),
    ('united-states.california.central-valley.clarksburg.merritt-island', 1, 1, 1),
    ('united-states.california.central-valley.diablo-grande', 2, 2, 1),
    ('united-states.california.central-valley.dunnigan-hills', 2, 2, 1),
    ('united-states.california.central-valley.madera', 4, 3, 1),
    ('united-states.california.central-valley.paulsell-valley', 1, 3, 1),
    ('united-states.california.central-valley.river-junction', 1, 1, 1),
    ('united-states.california.central-valley.salado-creek', 2, 3, 1),
    ('united-states.california.central-valley.tracy-hills', 2, 3, 1),
    ('united-states.california.central-valley.winters-highlands', 2, 6, 1),
    ('united-states.california.contra-costa', 1, 5, 1),
    ('united-states.california.covelo', 2, 2, 1),
    ('united-states.california.cucamonga-valley', 1, 5, 1),
    ('united-states.california.dos-rios', 1, 4, 1),
    ('united-states.california.inwood-valley', 1, 1, 1),
    ('united-states.california.leona-valley', 1, 2, 1),
    ('united-states.california.malibu-coast', 2, 5, 1),
    ('united-states.california.malibu-coast.malibu-newton-canyon', 2, 6, 1),
    ('united-states.california.malibu-coast.saddle-rock-malibu', 2, 4, 1),
    ('united-states.california.manton-valley', 1, 5, 1),
    ('united-states.california.north-coast.benmore-valley', 1, 1, 1),
    ('united-states.california.north-coast.clear-lake.big-valley-district-lake-county', 2, 5, 1),
    ('united-states.california.north-coast.clear-lake.kelsey-bench-lake-county', 2, 5, 1),
    ('united-states.california.north-coast.clear-lake.upper-lake-valley', 2, 2, 1),
    ('united-states.california.north-coast.cole-ranch', 2, 4, 1),
    ('united-states.california.north-coast.comptche', 1, 1, 1),
    ('united-states.california.north-coast.eagle-peak-mendocino-county', 1, 1, 1),
    ('united-states.california.north-coast.guenoc-valley', 2, 4, 1),
    ('united-states.california.north-coast.high-valley', 2, 6, 1),
    ('united-states.california.north-coast.long-valley-lake-county', 1, 4, 1),
    ('united-states.california.north-coast.mendocino.mcdowell-valley', 2, 3, 1),
    ('united-states.california.north-coast.mendocino.potter-valley', 2, 5, 1),
    ('united-states.california.north-coast.mendocino.redwood-valley', 1, 5, 1),
    ('united-states.california.north-coast.mendocino.yorkville-highlands', 2, 4, 1),
    ('united-states.california.north-coast.solano-county-green-valley', 1, 6, 1),
    ('united-states.california.north-coast.suisun-valley', 2, 6, 1),
    ('united-states.california.palos-verdes-peninsula', 2, 4, 1),
    ('united-states.california.seiad-valley', 1, 1, 1),
    ('united-states.california.sierra-foothills.north-yuba', 3, 5, 1),
    ('united-states.california.sierra-pelona-valley', 1, 1, 1),
    ('united-states.california.south-coast.ramona-valley', 2, 6, 1),
    ('united-states.california.south-coast.san-luis-rey', 2, 5, 1),
    ('united-states.california.south-coast.san-pasqual-valley', 2, 4, 1),
    ('united-states.california.squaw-valley-miramonte', 1, 2, 1),
    ('united-states.california.tehachapi-mountains', 1, 3, 1),
    ('united-states.california.trinity-lakes', 2, 6, 1),
    ('united-states.california.willow-creek', 2, 6, 1),
    ('united-states.california.yucaipa-valley', 1, 8, 1)
    ) as t(key, want_styles, want_grapes, want_article)
  loop
    select count(*) into n from public.wine_place_styles s
      join public.wine_places p on p.id = s.wine_place_id where p.canonical_key = r.key;
    if n <> r.want_styles then
      raise exception '%: % style rows, expected %', r.key, n, r.want_styles;
    end if;
    select count(*) into n from public.wine_place_grapes g
      join public.wine_places p on p.id = g.wine_place_id where p.canonical_key = r.key;
    if n <> r.want_grapes then
      raise exception '%: % grape rows, expected % — a grape name did not resolve', r.key, n, r.want_grapes;
    end if;
    select count(*) into n from public.wine_place_articles a
      join public.wine_places p on p.id = a.wine_place_id where p.canonical_key = r.key;
    if n < r.want_article then
      raise exception '%: no article', r.key;
    end if;
  end loop;

  -- No region or subregion in united-states is left without wine styles.
  select count(*) into n from public.wine_places p
   where p.kind in ('REGION','SUBREGION')
     and (p.canonical_key like 'united-states.%')
     and not exists (select 1 from public.wine_place_styles s where s.wine_place_id = p.id);
  if n <> 0 then raise exception '% places still have no wine styles', n; end if;

  -- Country level too: germany and spain always had rows and the other three
  -- did not, which was an inconsistency with no reason behind it.
  select count(*) into n from public.wine_places p
   where p.kind = 'COUNTRY' and (p.canonical_key like 'united-states')
     and not exists (select 1 from public.wine_place_styles s where s.wine_place_id = p.id);
  if n <> 0 then raise exception '% countries still have no wine styles', n; end if;

  -- ...or without an article.
  select count(*) into n from public.wine_places p
   where p.kind in ('REGION','SUBREGION')
     and (p.canonical_key like 'united-states.%')
     and not exists (select 1 from public.wine_place_articles a where a.wine_place_id = p.id);
  if n <> 0 then raise exception '% places still have no article', n; end if;
end $$;

